import{d as p,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第四十一章","description":"《正易心法》第四十一章——易道弥漫，九流可入：易本于阴阳，万物负阴而抱阳，故惟其所入；束于辞训则犯法，得悟则辞外见意、纵横妙用是为活法；当于羲皇心地上驰骋。","frontmatter":{"title":"正易心法·第四十一章","description":"《正易心法》第四十一章——易道弥漫，九流可入：易本于阴阳，万物负阴而抱阳，故惟其所入；束于辞训则犯法，得悟则辞外见意、纵横妙用是为活法；当于羲皇心地上驰骋。","category":"guide","aliases":["正易心法第四十一章","易道弥漫九流可入","活法与自悟"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-41.md","filePath":"yijing/zheng-yi-xin-fa/chapter-41.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-41.md"},x=p({...c,setup(u){const i=[{id:"z41-01",label:"一、易道弥漫",showLabel:!0,sentences:[["易道",{text:"弥漫",glossary:"miman"},"，",{text:"九流",glossary:"jiuliu"},"可入。当知",{text:"活法",glossary:"huofa"},"，要须",{text:"自悟",glossary:"ziwu"},"。"]],note:["《易》道充满一切，九流百家皆可从中入门；应当知道「活法」，关键在于自己领悟。（**本章是全书正文的最后一章，也是方法论的总收束**——前四十章教了那么多象数义理，最后这一章说的是：**这一切，都只是入门的路；真正的目的是自悟活法。**）"]},{id:"z41-02",label:"二、负阴而抱阳",showLabel:!0,sentences:[["《易》之为书，本于阴阳。万物负阴而抱阳，何适而非阴阳也？是以在人惟其所入耳。"]],note:["《易》这部书本于阴阳。万物负阴而抱阳，哪里不是阴阳呢？所以对人来说，只在于从哪个角度入门。（**「万物负阴而抱阳」出《老子》四十二章**。**「何适而非阴阳」是本章能成立的前提**：**任何学问、任何事物都在阴阳之中，所以任何领域都可以入《易》。**）"]},{id:"z41-03",label:"三、各以其道入",showLabel:!0,sentences:[["文王、周公以",{text:"庶类",glossary:"shulei"},"入，宣父以",{text:"八物",glossary:"bawu"},"入，斯其上也。其后或以",{text:"律度",glossary:"lüdu"},"入，或以",{text:"历数",glossary:"lishu"},"入，或以",{text:"仙道",glossary:"xiandao"},"入。以此知《易》道无往而不可也。"]],note:["文王、周公从万事万物的变化来入，孔子从八卦所象之物来入——这是最高的入法；此后有人从音律度量来入，有人从历法数术来入，有人从仙道修炼来入。由此可知，《易》道无处不可通达。（**两层的分辨**：**「庶类」是最宽广的入法**（从万类的共同规律入手），**「八物」是最精准的入法**（以具体的象把握抽象的理）；**律度、历数、仙道则是从某一专门领域切入**，各有所得而较窄。）"]},{id:"z41-04",label:"四、束于辞训",showLabel:!0,sentences:[["苟惟束于",{text:"辞训",glossary:"cixun"},"，则是",{text:"犯法",glossary:"fanfa"},"也，良田未得悟耳。"]],note:["如果只是被文字训诂束缚，那就是违背了易的活法——正是因为没有得到领悟。（**这是本书批评的最后一站**：从第一章「不知落处」到本章「束于辞训」，**麻衣批的始终是同一件事：把活的做成死的。** 原文「良田」当为「良由」之讹——「由」字上部未封口，被误写为「田」；「良由未得悟耳」意为「正是因为还没有得到领悟」。）"]},{id:"z41-05",label:"五、是为活法",showLabel:!0,sentences:[["果得悟焉，则",{text:"辞外见意",glossary:"ciwaiJianyi"},"，而纵横妙用，唯吾所欲，是为活法也。"]],note:["果真得到了领悟，就能在文字之外看见意义，纵横妙用、随心所欲——这就是活法。（**「纵横妙用，唯吾所欲」不是「随便乱用」**，而是**「随心所用而皆合于理」**——**就像一个真正的书法家，不再想着笔法规则，但每一笔都合于法度。规则内化了，所以忘记了规则，但处处都是规则。** 这就是本章「活法」的完整含义：**不是无法，是法已入心。**）"]},{id:"z41-06",label:"六、羲皇心地",showLabel:!0,sentences:[["故曰：“学《易》者当于羲皇心地上",{text:"驰骋",glossary:"chicheng"},"，无于周、孔言语下",{text:"拘挛",glossary:"juluan"},"。”"]],note:["所以说：「学《易》的人应当在伏羲的心灵境界上自由驰骋，不要在周文王、周公、孔子的文字语言下拘束蜷缩。」（**两个层次**：**羲皇心地**＝《易》的源头，无文字的直接感知；**周孔言语**＝《易》的传承，是工具而非目的。**与禅宗「以指指月，见月忘指」完全一致**：文字是手指，羲皇心地是月亮——**看见月亮之后，不要再盯着手指。**）"]}],o=[{id:"miman",term:"弥漫",pinyin:"mí màn",meaning:"充满、遍布。《易》道充满一切，无处不在。"},{id:"jiuliu",term:"九流",pinyin:"jiǔ liú",meaning:"先秦九大学派（儒、道、阴阳、法、名、墨、纵横、杂、农），泛指各种学问路径。"},{id:"huofa",term:"活法",pinyin:"huó fǎ",meaning:"活的方法、灵活的法则。对应「死法」（僵化的规则），是本章核心词。"},{id:"ziwu",term:"自悟",pinyin:"zì wù",meaning:"自己领悟。不能靠别人传授，必须自己体悟。"},{id:"shulei",term:"庶类",pinyin:"shù lèi",meaning:"众多事物、万类。文王周公从万事万物的变化来理解易。"},{id:"bawu",term:"八物",pinyin:"bā wù",meaning:"八卦所象之物。孔子以八物入，是「最精准的入法」。"},{id:"lüdu",term:"律度",pinyin:"lǜ dù",meaning:"音律与度量。以音律、度量衡的数理来入易。"},{id:"lishu",term:"历数",pinyin:"lì shù",meaning:"历法与数术。以天文历法来入易。"},{id:"xiandao",term:"仙道",pinyin:"xiān dào",meaning:"道教修炼之道。以内丹、修仙来入易。"},{id:"cixun",term:"辞训",pinyin:"cí xùn",meaning:"文字训诂。束于辞训即只在字词解释上打转，不得真义。"},{id:"fanfa",term:"犯法",pinyin:"fàn fǎ",meaning:"违犯法度。此处「法」指易的活法——束于辞训反而违背了易的精神。"},{id:"ciwaiJianyi",term:"辞外见意",pinyin:"cí wài jiàn yì",meaning:"在文字之外看见意义。第六章的核心命题，本章是它的最终落实（活法）。"},{id:"chicheng",term:"驰骋",pinyin:"chí chěng",meaning:"骑马奔驰。自由奔放，不受拘束。"},{id:"juluan",term:"拘挛",pinyin:"jū luán",meaning:"拘束、蜷缩。被文字束缚，无法自由。"}];return(b,n)=>{const l=s("DaoTextReading"),r=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t(`<h1 id="正易心法·第四十一章" tabindex="-1">正易心法·第四十一章 <a class="header-anchor" href="#正易心法·第四十一章" aria-label="Permalink to &quot;正易心法·第四十一章&quot;">​</a></h1><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>本章是<strong>全书正文的最后一章</strong>，也是<strong>方法论的总收束</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>核心命题：易道弥漫，九流可入；当知活法，要须自悟</span></span>
<span class="line"><span></span></span>
<span class="line"><span>三层：</span></span>
<span class="line"><span>  一、《易》是开放的（九流可入）</span></span>
<span class="line"><span>  二、入门有高下之分（庶类／八物 vs 律度／历数／仙道 vs 辞训）</span></span>
<span class="line"><span>  三、真正的目标是活法（辞外见意，羲皇心地）</span></span></code></pre></div><p><strong>麻衣的最终立场</strong>：<strong>不是「这样读易才对」，而是「读易最终要超越读易」</strong>——<strong>得鱼忘筌，得意忘言。</strong></p><h2 id="为什么重要" tabindex="-1">为什么重要 <a class="header-anchor" href="#为什么重要" aria-label="Permalink to &quot;为什么重要&quot;">​</a></h2><p><strong>入《易》的三个层次</strong>：</p><table tabindex="0"><thead><tr><th>层次</th><th>入法</th><th>说明</th></tr></thead><tbody><tr><td><strong>最高</strong></td><td>文王周公以<strong>庶类</strong>入、孔子以<strong>八物</strong>入</td><td>最宽广 / 最精准</td></tr><tr><td><strong>中间</strong></td><td>律度入、历数入、仙道入</td><td>各有所得，但较窄</td></tr><tr><td><strong>最低</strong></td><td>束于辞训</td><td>只在文字上打转，且走偏了</td></tr></tbody></table><p><strong>「活法」与「死法」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>死法（束于辞训）：</span></span>
<span class="line"><span>  把《易》的文字当作规则，逐字逐句解释，不敢越雷池一步</span></span>
<span class="line"><span>  = 文字是边界，义理被关在文字里面</span></span>
<span class="line"><span></span></span>
<span class="line"><span>活法（辞外见意）：</span></span>
<span class="line"><span>  把《易》的文字当作窗口，透过文字看见文字背后的义理</span></span>
<span class="line"><span>  = 文字是跳板，义理在文字之外自由流动</span></span>
<span class="line"><span></span></span>
<span class="line"><span>活法的条件：「要须自悟」</span></span>
<span class="line"><span>  活法是「辞外见意」，而「辞外」的东西无法用「辞」来传递</span></span>
<span class="line"><span>  用文字教人「超越文字」，本身就是一个悖论</span></span>
<span class="line"><span>  所以麻衣说「自悟」——只有自己跨过那道门槛，才算真正进入活法</span></span></code></pre></div><p><strong>「纵横妙用，唯吾所欲」不是「随便乱用」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>而是「随心所用而皆合于理」</span></span>
<span class="line"><span>就像一个真正的书法家：不再想着笔法规则，但每一笔都合于法度</span></span>
<span class="line"><span>= 规则内化了，所以忘记了规则，但处处都是规则</span></span></code></pre></div><p><strong>「羲皇心地」vs「周孔言语」</strong>：</p><table tabindex="0"><thead><tr><th></th><th>性质</th><th>地位</th></tr></thead><tbody><tr><td>羲皇心地</td><td>伏羲画卦时的那个状态：无文字，只有对天地的直接感知</td><td>《易》的源头，<strong>目的地</strong></td></tr><tr><td>周孔言语</td><td>卦辞、爻辞、十翼，是文字化的《易》</td><td>《易》的传承，<strong>是路</strong></td></tr></tbody></table><p><strong>文王周公孔子是最好的「路」，伏羲的心地是最好的「目的地」</strong>——<strong>走最好的路，到达最终的目的地，然后在那里自由驰骋。</strong></p><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li>先看三层入法的高下：<strong>庶类／八物 → 律度／历数／仙道 → 辞训</strong>；</li><li>再分清「活法」与「死法」：<strong>一个把文字当边界，一个把文字当窗口</strong>；</li><li>最后读末句引文——<strong>这是全书正文的最后一句。</strong></li></ol><h2 id="核心内容要点" tabindex="-1">核心内容要点 <a class="header-anchor" href="#核心内容要点" aria-label="Permalink to &quot;核心内容要点&quot;">​</a></h2><ul><li><strong>九流可入</strong>：万物负阴而抱阳，故无处不可入。</li><li><strong>圣人之入</strong>：庶类（最宽）、八物（最精）。</li><li><strong>后学之入</strong>：律度、历数、仙道（较窄）。</li><li><strong>束于辞训</strong>：犯法，未得悟。</li><li><strong>辞外见意</strong>：是为活法。</li><li><strong>羲皇心地</strong>：驰骋于此，不拘于周孔言语。</li></ul><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2>`,20)),e(l,{colophon:"九流可入 · 当知活法 · 要须自悟 · 羲皇心地",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第四十一章原文",sections:i,glossary:o}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「良田未得悟耳」之「良田」当为「良由」之形讹（「由」字上部未封口而误作「田」），全句意为「正是因为还没有得到领悟」；此处依底本录入、以上文说明，不作径改。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(r,{items:[{term:"九流可入",pinyin:["jiǔ","liú"],meaning:"万物负阴而抱阳，任何学问都在阴阳之中——故任何领域都可以入《易》，《易》非一家的专属。"},{term:"活法与死法",pinyin:["huó","fǎ"],meaning:"死法：把文字当边界（束于辞训）；活法：把文字当窗口（辞外见意）。规则内化后忘了规则，才是活法。"},{term:"要须自悟",pinyin:["zì","wù"],meaning:"活法不能被教，只能被悟——因为「辞外」的东西无法用「辞」来传递。"},{term:"羲皇心地",pinyin:["xī","huáng"],meaning:"伏羲画卦时的那个状态：无文字，只对天地直接感知。是《易》的源头，也是最终的目的地。"},{term:"周孔言语",pinyin:["zhōu","kǒng"],meaning:"卦辞、爻辞、十翼。是《易》的传承，是「最好的路」——但路不是目的地。"}]}),n[3]||(n[3]=t(`<h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一章在说什么" tabindex="-1">象：这一章在说什么 <a class="header-anchor" href="#象-这一章在说什么" aria-label="Permalink to &quot;象：这一章在说什么&quot;">​</a></h3><p>本章是<strong>全书正文的最后一章</strong>，也是方法论的总收束：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一、《易》是开放的（九流可入）</span></span>
<span class="line"><span>二、入门有高下之分（庶类／八物 → 律度／历数／仙道 → 辞训）</span></span>
<span class="line"><span>三、真正的目标是活法（辞外见意，羲皇心地）</span></span></code></pre></div><h3 id="理-为什么这样说" tabindex="-1">理：为什么这样说 <a class="header-anchor" href="#理-为什么这样说" aria-label="Permalink to &quot;理：为什么这样说&quot;">​</a></h3><p><strong>「活法」与「死法」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>死法（束于辞训）：文字是边界，义理被关在文字里面</span></span>
<span class="line"><span>活法（辞外见意）：文字是跳板，义理在文字之外自由流动</span></span>
<span class="line"><span></span></span>
<span class="line"><span>活法的条件：「要须自悟」</span></span>
<span class="line"><span>  活法是「辞外见意」，而「辞外」的东西无法用「辞」来传递</span></span>
<span class="line"><span>  用文字教人「超越文字」，本身就是一个悖论</span></span></code></pre></div><p><strong>「羲皇心地」vs「周孔言语」</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>羲皇心地（伏羲）= 无文字，直接感知天地 = 《易》的源头，目的地</span></span>
<span class="line"><span>周孔言语（文王周公孔子）= 卦辞爻辞十翼 = 《易》的传承，是路</span></span>
<span class="line"><span></span></span>
<span class="line"><span>文王周公孔子是最好的「路」，伏羲的心地是最好的「目的地」</span></span></code></pre></div><p><strong>与第四十二章的关系</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>第四十一章：「要须自悟」「于羲皇心地上驰骋」</span></span>
<span class="line"><span>第四十二章：世俗溺辞，羲皇初意不行于世 ——「呜乎」</span></span>
<span class="line"><span>= 两章是同一个问题的两面：一是「应该怎样」，一是「实际怎样」</span></span></code></pre></div><h3 id="用-今天怎么进入这一章" tabindex="-1">用：今天怎么进入这一章 <a class="header-anchor" href="#用-今天怎么进入这一章" aria-label="Permalink to &quot;用：今天怎么进入这一章&quot;">​</a></h3><ul><li>分清三层入法：<strong>庶类／八物 → 律度／历数／仙道 → 辞训</strong>；</li><li>记住「活法」的定义：<strong>规则内化之后忘了规则</strong>；</li><li>顺着钩子想（承接昇哥的问题）：<strong>「自悟」能被教吗？</strong> 我的看法：<strong>不能直接教，但可以被制造条件。</strong> 就像禅师的棒喝——<strong>不是为了传递什么，是为了让人自己跨过去。</strong> 麻衣的四十一章，<strong>每一章的「留一个思考钩子」，就是在制造这种契机。</strong> 所以这本书的写法本身就是一种「活法」：<strong>它不给你答案，它把你的手放在门上。</strong> 这也解释了「要须自悟」为什么不是推卸——<strong>它是唯一诚实的说法。</strong></li></ul><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《易》道充满一切，九流百家皆可从中入门；应当知道「活法」，关键在于自己领悟。</p><p>《易》这部书本于阴阳。万物负阴而抱阳，哪里不是阴阳呢？所以对人来说，只在于从哪个角度入门。</p><p>文王、周公从万事万物的变化来入，孔子从八卦所象之物来入——这是最高的入法；此后有人从音律度量来入，有人从历法数术来入，有人从仙道修炼来入。由此可知，《易》道无处不可通达。</p><p>如果只是被文字训诂束缚，那就是违背了易的活法——正是因为还没有得到领悟。</p><p>果真得到了领悟，就能在文字之外看见意义，纵横妙用、随心所欲——这就是活法。</p><p>所以说：「学《易》的人应当在伏羲的心灵境界上自由驰骋，不要在周文王、周公、孔子的文字语言下拘束蜷缩。」</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p><strong>一句话</strong>：第四十一章是全书正文的收尾，也是麻衣最「松手」的一章——<strong>他讲了四十章，最后说：这些只是路，你要自己走到那个没路的地方。</strong></p></blockquote><p>可以按这几条慢慢写：</p><ul><li><strong>「九流可入」</strong>——这是全书最开放的一句话。<strong>为什么能开放？因为「万物负阴而抱阳」——什么都在阴阳里，所以什么都能入易。</strong></li><li><strong>三层入法</strong>——庶类（最宽）、八物（最精）、律度历数仙道（较专）、辞训（走偏）。<strong>麻衣不是在评高下，是在画一条偏离的轨迹：入易的方式越窄，离源头越远。</strong></li><li><strong>「活法」与「死法」</strong>——<strong>这是我读完全书最有共鸣的一组词。</strong> 死法是把文字当边界；活法是把文字当窗口。<strong>但活法不是「不守规则」，是「规则内化到忘了规则」。</strong> 就像书法家。</li><li><strong>「要须自悟」</strong>——不是推卸，是<strong>唯一诚实的说法</strong>：<strong>「辞外」的东西，用「辞」教不了。</strong></li><li><strong>「羲皇心地」</strong>——<strong>这是全书最亮的四个字</strong>：不是某个道理，是<strong>一个状态</strong>。<strong>不是「你知道什么」，是「你在哪里」。</strong></li><li><strong>留给自己的问题</strong>（承接昇哥的钩子）：<strong>「自悟」能被教吗？</strong> 我的看法：<strong>不能直接教，但可以被制造条件。</strong> 就像禅师的棒喝——<strong>不是为了传递什么，是为了让人自己跨过去。</strong> 麻衣的四十一章，<strong>每一章的「留一个思考钩子」，就是在制造这种契机。</strong> 所以这本书的写法本身就是一种活法：<strong>它不给你答案，它把你的手放在门上。</strong></li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/yijing/zheng-yi-xin-fa/">正易心法总览</a></li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-06">第六章 · 消息卦画</a> — 「辞外见意」（本章的活法即其落实）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-24">第二十四章 · 见于日用</a> — 「《易》在日用」（本章的开放性与之一贯）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-40">第四十章 · 非训变易</a> — 「大易」（本章由「易是什么」转入「怎么学」）</li><li><a href="/Dao/yijing/zheng-yi-xin-fa/chapter-42">第四十二章 · 舛讹为多</a> — 「呜乎」（「应该怎样」与「实际怎样」）</li><li><a href="/Dao/yijing/shi-yi/xi-ci-zhuan-shang">系辞上传</a> — 「《易》与天地准」（本章说九流皆可入）</li></ul>`,26))])}}});export{y as __pageData,x as default};
